interface Org {
  id: string;
  name?: string;
}

interface User {
  id: string;
  orgId: string;
  org?: Org;
}

async function loadUser(id: string): Promise<User> {
  const userRes = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!userRes.ok) {
    throw new Error(`Failed to load user ${id}: ${userRes.status}`);
  }

  const user = (await userRes.json()) as User;

  const orgRes = await fetch(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  if (!orgRes.ok) {
    throw new Error(`Failed to load org ${user.orgId}: ${orgRes.status}`);
  }

  user.org = (await orgRes.json()) as Org;
  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };

